{
    "name": "092_gqa_attention_with_qk_norm",
    "hf_id": "zai-org/GLM-4.5-Air",
    "description": "Grouped Query Attention with QK normalization for GLM-4. Includes Q/K/V projections, RMSNorm on Q/K, RoPE, GQA with 96 query heads and 8 KV heads (12x repetition), scaled dot-product attention with causal mask, and output projection.",
    "axes": {
        "batch_size": {
            "type": "var"
        },
        "seq_len": {
            "type": "var"
        },
        "hidden_size": {
            "type": "const",
            "value": 4096
        },
        "num_attention_heads": {
            "type": "const",
            "value": 96
        },
        "num_key_value_heads": {
            "type": "const",
            "value": 8
        },
        "head_dim": {
            "type": "const",
            "value": 128
        },
        "q_out_features": {
            "type": "expr",
            "expression": "num_attention_heads * head_dim"
        },
        "kv_out_features": {
            "type": "expr",
            "expression": "num_key_value_heads * head_dim"
        }
    },
    "custom_inputs_entrypoint": null,
    "inputs": {
        "hidden_states": {
            "shape": [
                "batch_size",
                "seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Input hidden states"
        },
        "q_proj_weight": {
            "shape": [
                "q_out_features",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Q projection weight"
        },
        "q_proj_bias": {
            "shape": [
                "q_out_features"
            ],
            "dtype": "bfloat16",
            "description": "Q projection bias"
        },
        "k_proj_weight": {
            "shape": [
                "kv_out_features",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "K projection weight"
        },
        "k_proj_bias": {
            "shape": [
                "kv_out_features"
            ],
            "dtype": "bfloat16",
            "description": "K projection bias"
        },
        "v_proj_weight": {
            "shape": [
                "kv_out_features",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "V projection weight"
        },
        "v_proj_bias": {
            "shape": [
                "kv_out_features"
            ],
            "dtype": "bfloat16",
            "description": "V projection bias"
        },
        "o_proj_weight": {
            "shape": [
                "hidden_size",
                "q_out_features"
            ],
            "dtype": "bfloat16",
            "description": "Output projection weight"
        },
        "q_norm_weight": {
            "shape": [
                "head_dim"
            ],
            "dtype": "bfloat16",
            "description": "Q RMSNorm weight"
        },
        "k_norm_weight": {
            "shape": [
                "head_dim"
            ],
            "dtype": "bfloat16",
            "description": "K RMSNorm weight"
        },
        "cos": {
            "shape": [
                "batch_size",
                "seq_len",
                "head_dim"
            ],
            "dtype": "bfloat16",
            "description": "Cosine for RoPE"
        },
        "sin": {
            "shape": [
                "batch_size",
                "seq_len",
                "head_dim"
            ],
            "dtype": "bfloat16",
            "description": "Sine for RoPE"
        },
        "rms_norm_eps": {
            "shape": null,
            "dtype": "float32",
            "description": "RMSNorm epsilon"
        }
    },
    "outputs": {
        "output": {
            "shape": [
                "batch_size",
                "seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Attention output"
        }
    },
    "reference": "import torch\nimport torch.nn.functional as F\n\n@torch.no_grad()\ndef run(\n    hidden_states: torch.Tensor,\n    q_proj_weight: torch.Tensor,\n    q_proj_bias: torch.Tensor,\n    k_proj_weight: torch.Tensor,\n    k_proj_bias: torch.Tensor,\n    v_proj_weight: torch.Tensor,\n    v_proj_bias: torch.Tensor,\n    o_proj_weight: torch.Tensor,\n    q_norm_weight: torch.Tensor,\n    k_norm_weight: torch.Tensor,\n    cos: torch.Tensor,\n    sin: torch.Tensor,\n    rms_norm_eps: float,\n):\n    batch_size, seq_length, _ = hidden_states.shape\n    num_attention_heads = 96\n    num_key_value_heads = 8\n    head_dim = 128\n    num_key_value_groups = 12\n    scaling = head_dim ** -0.5\n    \n    # Q/K/V projections\n    query_states = F.linear(hidden_states, q_proj_weight, q_proj_bias)\n    key_states = F.linear(hidden_states, k_proj_weight, k_proj_bias)\n    value_states = F.linear(hidden_states, v_proj_weight, v_proj_bias)\n    \n    # Reshape to separate heads\n    query_states = query_states.view(batch_size, seq_length, num_attention_heads, head_dim)\n    key_states = key_states.view(batch_size, seq_length, num_key_value_heads, head_dim)\n    value_states = value_states.view(batch_size, seq_length, num_key_value_heads, head_dim)\n    \n    # Apply QK RMSNorm\n    def rms_norm(x, weight):\n        input_dtype = x.dtype\n        x = x.to(torch.float32)\n        variance = x.pow(2).mean(-1, keepdim=True)\n        x = x * torch.rsqrt(variance + rms_norm_eps)\n        return (weight * x).to(input_dtype)\n    \n    query_states = rms_norm(query_states, q_norm_weight)\n    key_states = rms_norm(key_states, k_norm_weight)\n    \n    # Transpose to [batch, num_heads, seq_len, head_dim]\n    query_states = query_states.transpose(1, 2)\n    key_states = key_states.transpose(1, 2)\n    value_states = value_states.transpose(1, 2)\n    \n    # Apply RoPE\n    cos_expanded = cos.unsqueeze(1)  # [batch, 1, seq_len, head_dim]\n    sin_expanded = sin.unsqueeze(1)\n    \n    # Rotate half for Q\n    q1, q2 = query_states[..., :64], query_states[..., 64:]\n    q_rot_half = torch.cat((-q2, q1), dim=-1)\n    query_states = (query_states * cos_expanded) + (q_rot_half * sin_expanded)\n    \n    # Rotate half for K\n    k1, k2 = key_states[..., :64], key_states[..., 64:]\n    k_rot_half = torch.cat((-k2, k1), dim=-1)\n    key_states = (key_states * cos_expanded) + (k_rot_half * sin_expanded)\n    \n    # Repeat KV heads for GQA: [batch, 8, seq_len, 128] -> [batch, 96, seq_len, 128]\n    key_states = key_states[:, :, None, :, :].expand(\n        batch_size, num_key_value_heads, num_key_value_groups, seq_length, head_dim\n    ).reshape(batch_size, num_attention_heads, seq_length, head_dim)\n    value_states = value_states[:, :, None, :, :].expand(\n        batch_size, num_key_value_heads, num_key_value_groups, seq_length, head_dim\n    ).reshape(batch_size, num_attention_heads, seq_length, head_dim)\n    \n    # Compute attention scores\n    attn_weights = torch.matmul(query_states, key_states.transpose(2, 3)) * scaling\n    \n    # Apply causal mask\n    causal_mask = torch.triu(\n        torch.full((seq_length, seq_length), float('-inf'), device=hidden_states.device, dtype=attn_weights.dtype),\n        diagonal=1\n    )\n    attn_weights = attn_weights + causal_mask\n    \n    # Softmax\n    attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query_states.dtype)\n    \n    # Compute attention output\n    attn_output = torch.matmul(attn_weights, value_states)\n    \n    # Transpose and reshape\n    attn_output = attn_output.transpose(1, 2).contiguous()\n    attn_output = attn_output.reshape(batch_size, seq_length, num_attention_heads * head_dim)\n    \n    # Output projection (no bias)\n    output = F.linear(attn_output, o_proj_weight, None)\n    \n    return output\n"
}

